/**
 * CommunitySystem - 社区功能系统
 * 基于 nanobot community 架构
 * 用户评分、评论、打赏功能
 */
import { toolRegistry } from './registry.js';
import { getToolRating, submitRating, getFavorites } from './ToolRating.js';

// 社区数据存储
const COMMUNITY_KEY = 'ai-creator-community';

// 预设头像
const AVATARS = ['🐱', '🐶', '🐼', '🐨', '🐯', '🦁', '🐮', '🐷', '🐸', '🐵', '🐰', '🐻', '🐨', '🦊', '🦝', '🐻‍❄️', '🦄', '🐲', '🦋', '🐝'];

// 预设用户名
const NICKNAMES = [
  '创作者A', '开发者B', '设计师C', '音乐人D', '画家E',
  '写作者F', '导演G', '摄影师H', '动画师I', '制作人J',
  '极客侠', '创意王', '灵感家', '梦想家', '执行者'
];

/**
 * 获取社区数据
 */
export function getCommunityData() {
  try {
    return JSON.parse(localStorage.getItem(COMMUNITY_KEY) || '{}');
  } catch {
    return {};
  }
}

/**
 * 保存社区数据
 */
function saveCommunityData(data) {
  localStorage.setItem(COMMUNITY_KEY, JSON.stringify(data));
}

/**
 * 获取工具的社区信息
 */
export function getToolCommunity(toolId) {
  const data = getCommunityData();
  const toolData = data[toolId] || {
    reviews: [],
    tips: [],
    likes: 0,
    views: 0,
    lastActivity: null
  };
  
  return {
    ...toolData,
    reviewCount: toolData.reviews.length,
    tipCount: toolData.tips.length
  };
}

/**
 * 提交评论
 */
export function submitReview(toolId, comment, rating) {
  const data = getCommunityData();
  
  if (!data[toolId]) {
    data[toolId] = { reviews: [], tips: [], likes: 0, views: 0, lastActivity: null };
  }
  
  const review = {
    id: 'review_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6),
    comment,
    rating: rating || 5,
    author: {
      nickname: NICKNAMES[Math.floor(Math.random() * NICKNAMES.length)],
      avatar: AVATARS[Math.floor(Math.random() * AVATARS.length)]
    },
    createdAt: Date.now(),
    likes: 0
  };
  
  data[toolId].reviews.unshift(review);
  data[toolId].lastActivity = Date.now();
  
  saveCommunityData(data);
  
  return review;
}

/**
 * 点赞评论
 */
export function likeReview(toolId, reviewId) {
  const data = getCommunityData();
  if (!data[toolId]) return false;
  
  const review = data[toolId].reviews.find(r => r.id === reviewId);
  if (review) {
    review.likes++;
    saveCommunityData(data);
    return true;
  }
  return false;
}

/**
 * 删除评论
 */
export function deleteReview(toolId, reviewId) {
  const data = getCommunityData();
  if (!data[toolId]) return false;
  
  const idx = data[toolId].reviews.findIndex(r => r.id === reviewId);
  if (idx >= 0) {
    data[toolId].reviews.splice(idx, 1);
    saveCommunityData(data);
    return true;
  }
  return false;
}

/**
 * 提交技巧分享
 */
export function submitTip(toolId, title, content) {
  const data = getCommunityData();
  
  if (!data[toolId]) {
    data[toolId] = { reviews: [], tips: [], likes: 0, views: 0, lastActivity: null };
  }
  
  const tip = {
    id: 'tip_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6),
    title,
    content,
    author: {
      nickname: NICKNAMES[Math.floor(Math.random() * NICKNAMES.length)],
      avatar: AVATARS[Math.floor(Math.random() * AVATARS.length)]
    },
    createdAt: Date.now(),
    likes: 0
  };
  
  data[toolId].tips.unshift(tip);
  data[toolId].lastActivity = Date.now();
  
  saveCommunityData(data);
  
  return tip;
}

/**
 * 点赞技巧
 */
export function likeTip(toolId, tipId) {
  const data = getCommunityData();
  if (!data[toolId]) return false;
  
  const tip = data[toolId].tips.find(t => t.id === tipId);
  if (tip) {
    tip.likes++;
    saveCommunityData(data);
    return true;
  }
  return false;
}

/**
 * 打赏工具
 */
export function tipTool(toolId, amount) {
  const data = getCommunityData();
  
  if (!data[toolId]) {
    data[toolId] = { reviews: [], tips: [], likes: 0, views: 0, lastActivity: null };
  }
  
  // 记录打赏
  if (!data[toolId].donations) {
    data[toolId].donations = [];
  }
  
  const donation = {
    id: 'donation_' + Date.now(),
    amount: amount || 10,
    author: {
      nickname: NICKNAMES[Math.floor(Math.random() * NICKNAMES.length)],
      avatar: AVATARS[Math.floor(Math.random() * AVATARS.length)]
    },
    createdAt: Date.now()
  };
  
  data[toolId].donations.push(donation);
  data[toolId].lastActivity = Date.now();
  
  saveCommunityData(data);
  
  return donation;
}

/**
 * 获取打赏排行榜
 */
export function getTopDonations(limit = 10) {
  const data = getCommunityData();
  const toolIds = Object.keys(data);
  const donations = [];
  
  for (const toolId of toolIds) {
    const toolData = data[toolId];
    if (toolData.donations && toolData.donations.length > 0) {
      const totalAmount = toolData.donations.reduce((sum, d) => sum + d.amount, 0);
      const tool = toolRegistry.getTool(toolId);
      donations.push({
        toolId,
        toolName: tool ? tool.name : toolId,
        totalAmount,
        donationCount: toolData.donations.length
      });
    }
  }
  
  return donations
    .sort((a, b) => b.totalAmount - a.totalAmount)
    .slice(0, limit);
}

/**
 * 获取活跃社区工具
 */
export function getActiveCommunityTools(limit = 10) {
  const data = getCommunityData();
  const toolIds = Object.keys(data);
  
  const activeTools = toolIds
    .filter(id => {
      const toolData = data[id];
      return toolData.reviews.length > 0 || toolData.tips.length > 0;
    })
    .map(id => {
      const toolData = data[id];
      const tool = toolRegistry.getTool(id);
      return {
        toolId: id,
        toolName: tool ? tool.name : id,
        toolIcon: tool ? tool.icon : '🔧',
        reviewCount: toolData.reviews.length,
        tipCount: toolData.tips.length,
        totalLikes: 
          toolData.reviews.reduce((sum, r) => sum + r.likes, 0) +
          toolData.tips.reduce((sum, t) => sum + t.likes, 0),
        lastActivity: toolData.lastActivity || 0
      };
    })
    .sort((a, b) => b.lastActivity - a.lastActivity)
    .slice(0, limit);
  
  return activeTools;
}

/**
 * 记录工具浏览
 */
export function recordToolView(toolId) {
  const data = getCommunityData();
  
  if (!data[toolId]) {
    data[toolId] = { reviews: [], tips: [], likes: 0, views: 0, lastActivity: null };
  }
  
  data[toolId].views++;
  saveCommunityData(data);
}

/**
 * 获取热门工具（基于社区活跃度）
 */
export function getHotCommunityTools(limit = 10) {
  const data = getCommunityData();
  const toolIds = Object.keys(data);
  
  const hotTools = toolIds
    .filter(id => {
      const toolData = data[id];
      return toolData.views > 0 || toolData.reviews.length > 0;
    })
    .map(id => {
      const toolData = data[id];
      const tool = toolRegistry.getTool(id);
      
      // 计算热度分数
      const hotScore = 
        toolData.views * 1 +
        toolData.reviews.length * 5 +
        toolData.tips.length * 8 +
        toolData.reviews.reduce((sum, r) => sum + r.likes, 0) * 3 +
        toolData.tips.reduce((sum, t) => sum + t.likes, 0) * 3 +
        (toolData.donations ? toolData.donations.reduce((sum, d) => sum + d.amount, 0) * 10 : 0);
      
      return {
        toolId: id,
        toolName: tool ? tool.name : id,
        toolIcon: tool ? tool.icon : '🔧',
        views: toolData.views,
        reviewCount: toolData.reviews.length,
        tipCount: toolData.tips.length,
        hotScore
      };
    })
    .sort((a, b) => b.hotScore - a.hotScore)
    .slice(0, limit);
  
  return hotTools;
}

/**
 * 清除社区数据
 */
export function clearCommunityData() {
  localStorage.removeItem(COMMUNITY_KEY);
}

export default {
  getCommunityData,
  getToolCommunity,
  submitReview,
  likeReview,
  deleteReview,
  submitTip,
  likeTip,
  tipTool,
  getTopDonations,
  getActiveCommunityTools,
  recordToolView,
  getHotCommunityTools,
  clearCommunityData
};